document.addEventListener('input',event=>{
 const target=event.target;if(target.id==='global-search'){renderSearch(target.value);return}
 if(target.matches('input[data-filter]')){clearTimeout(searchTimer);const value=target.value,key=target.dataset.filter,selection=target.selectionStart;searchTimer=setTimeout(()=>{updateFilters({[key]:value});const input=app.querySelector(`input[data-filter="${key}"]`);input?.focus();try{input?.setSelectionRange(selection,selection)}catch{}},180)}
});
document.addEventListener('change',event=>{const target=event.target;if(target.matches('select[data-filter]')){updateFilters({[target.dataset.filter]:target.value});return}switch(target.dataset.change){case 'density':state.density=target.checked?'compact':'comfortable';safeSave('alice-density',state.density);render();break;case 'language':state.lang=target.value;safeSave('alice-lang',state.lang);render();break;case 'role':state.role=target.value;if(!canSeeAudit())state.overview='operations';render();toast(t('Preview role updated.','Önizleme rolü güncellendi.'));break;case 'license':state.license=target.value;render();break}});
document.addEventListener('submit',event=>{
 const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const data=new FormData(form),kind=form.dataset.form;
 if(kind==='login'){stepUp('demo-login',t('Confirm it’s you','Siz olduğunuzu doğrulayın'),`<p class="small">${t('Enter the 6-digit code from your authenticator.','Doğrulayıcınızdaki 6 haneli kodu girin.')}</p>`);return}
 if(kind==='step-up'){if(data.get('verification-code')!=='123456'){form.querySelector('#verification-error').textContent=t('Use the demo code 123456 to continue.','Devam etmek için 123456 örnek kodunu kullanın.');return}const pending=state.modal;closeModal();if(pending?.action==='demo-login'){go('overview');return}if(pending?.action==='license-activate'){state.license='active';go('license');toast(t('Sample license activated.','Örnek lisans etkinleştirildi.'));return}openModal(t('Identity check demonstrated','Kimlik kontrolü gösterildi'),t('Sample confirmation','Örnek onay'),notice(t('Verification step completed in the prototype','Prototip doğrulama adımı tamamlandı'),t('No credentials, secrets or external systems were accessed. Production executes the authorized action only after a real server-side verification.','Kimlik bilgilerine, gizli verilere veya dış sistemlere erişilmedi. Üretimde yetkili işlem ancak gerçek sunucu doğrulamasından sonra yürütülür.'))+demoNotice(),btn(t('Done','Tamam'),'close-modal','Check','primary'));return}
 if(kind==='settings'){stepUp('save-settings',t('Save installation settings','Kurulum ayarlarını kaydet'),notice(t('Review changes before saving','Kaydetmeden önce değişiklikleri inceleyin'),t('This prototype demonstrates the verification flow. Configuration is not sent to any server.','Bu prototip doğrulama akışını gösterir. Yapılandırma sunucuya gönderilmez.')));return}
 if(kind==='save-view'){let views=[];try{views=JSON.parse(safeRead('alice-saved-views','[]'))}catch{}views.push({name:String(data.get('view-name')).trim(),query:query().toString()});safeSave('alice-saved-views',JSON.stringify(views));saveViewDialog();toast(t('View saved on this device.','Görünüm bu cihazda kaydedildi.'));return}
 if(kind==='upload-cert'){const name=String(data.get('certificate-label')||'new-service.atlas.example');const id='crt-'+(certificates.length+1);const c={...certificates[3],id,name,days:365,source:'uploaded',key:true,chain:true,locations:[],vault:null,notAfter:atDay(365),notBefore:atDay(0)};certificates.push(c);closeModal();go('certificates/'+id);toast(t('Sample certificate added. No file contents were uploaded.','Örnek sertifika eklendi. Dosya içeriği yüklenmedi.'));return}
 if(kind==='generate-key'){const name=String(data.get('key-label'));const id='key-'+(sshKeys.length+1);sshKeys.push({...sshKeys[0],id,name,type:String(data.get('key-type')),servers:0,rotation:'none',fingerprint:'SHA256:DEMO-ONLY-NO-REAL-KEY-GENERATED',managed:true});closeModal();go('ssh-keys/'+id);toast(t('Sample key added. No cryptographic key was generated.','Örnek anahtar eklendi. Gerçek kriptografik anahtar üretilmedi.'));return}
 if(kind==='create-csr'){closeModal();openModal(t('Signing request preview','İmza isteği önizlemesi'),String(data.get('csr-cn')),`<div class="facts">${fact(t('Common name','Ortak ad'),esc(data.get('csr-cn')))}${fact(t('Alternative names','Alternatif adlar'),esc(data.get('csr-sans')))}${fact(t('Algorithm','Algoritma'),esc(data.get('csr-type')))}</div><div class="mt24">${notice(t('Send the CSR to your certificate authority','CSR’yi sertifika otoritenize gönderin'),t('In production, Alice keeps the generated private key and later validates the signed certificate against it.','Üretimde Alice oluşturulan özel anahtarı saklar ve imzalı sertifikayı daha sonra bu anahtarla karşılaştırır.'))}</div>${demoNotice()}`,btn(t('Done','Tamam'),'close-modal','Check','primary'));return}
 if(kind==='add-target'){closeModal();openModal(t('Connection preview','Bağlantı önizlemesi'),esc(data.get('target-name')),`<div class="facts">${fact(t('Host','Sunucu'),esc(data.get('target-host'))+':'+esc(data.get('target-port')))}${fact(t('Platform','Platform'),esc(data.get('target-type')))}${fact(t('State','Durum'),badge(t('Awaiting host-key confirmation','Sunucu anahtarı onayı bekleniyor'),'warning'))}</div><div class="mt24">${notice(t('Next: review the observed fingerprint','Sonraki adım: gözlemlenen parmak izini inceleyin'),t('The production connection returns the real fingerprint. No network request was made here.','Üretim bağlantısı gerçek parmak izini getirir. Burada ağ isteği yapılmadı.'))}</div>${demoNotice()}`,btn(t('Done','Tamam'),'close-modal','Check','primary'));return}
 if(kind==='connect-vault'){stepUp('connect-vault',t('Confirm Key Vault connection','Key Vault bağlantısını doğrulayın'),`<div class="facts">${fact(t('Vault','Kasa'),esc(data.get('vault-name')))}${fact('URL',esc(data.get('vault-url')))}</div>`);return}
 if(kind==='create-policy'){closeModal();openModal(t('Policy preview','İlke önizlemesi'),sshKeys.find(k=>k.id===data.get('policy-key'))?.name,`<div class="facts">${fact(t('Interval','Aralık'),esc(data.get('policy-interval'))+' '+t('days','gün'))}${fact(t('Overlap','Geçiş'),esc(data.get('policy-overlap'))+' '+t('days','gün'))}${fact(t('Notice','Bildirim'),esc(data.get('policy-notice'))+' '+t('hours before','saat önce'))}</div><div class="mt24">${notice(t('Enabling a policy requires fresh verification','İlkeyi etkinleştirmek yeniden doğrulama gerektirir'),t('The real API returns a plan digest, affected locations and available actions.','Gerçek API plan özetini, etkilenen konumları ve kullanılabilir eylemleri döndürür.'))}</div>${demoNotice()}`,btn(t('Done','Tamam'),'close-modal','Check','primary'));return}
 if(kind==='upload-license'){stepUp('license-activate',t('Activate the sample license','Örnek lisansı etkinleştir'),`<div class="facts">${fact(t('Customer','Kurum'),'Atlas Infrastructure')}${fact(t('Target limit','Hedef sınırı'),'25')}${fact(t('Valid until','Bitiş'),'30 Sep 2027')}</div>`);return}
 if(kind==='change-password'&&data.get('new-password')!==data.get('confirm-password')){form.querySelector('[name=confirm-password]').setCustomValidity(t('Passwords do not match.','Parolalar eşleşmiyor.'));form.querySelector('[name=confirm-password]').reportValidity();form.querySelector('[name=confirm-password]').addEventListener('input',function(){this.setCustomValidity('')},{once:true});return}
 if(kind==='create-token'){stepUp('create-token',t('Confirm token creation','Belirteç oluşturmayı doğrulayın'),`<div class="facts">${fact(t('Name','Ad'),esc(data.get('token-name')))}${fact(t('Access','Erişim'),esc(data.get('token-scope')))}${fact(t('Expires in','Geçerlilik'),esc(data.get('token-days'))+' '+t('days','gün'))}</div>`);return}
 if(kind==='add-user'||kind==='manage-user'){stepUp('user-change',t('Confirm access change','Erişim değişikliğini doğrulayın'),notice(t('Administrative action','Yönetici işlemi'),t('The production API protects the last active administrator and records the change.','Üretim API’si son aktif yöneticiyi korur ve değişikliği kaydeder.')));return}
 closeModal();toast(t('Sample form validated. No production data changed.','Örnek form doğrulandı. Üretim verileri değiştirilmedi.'));
});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch()}if(event.key==='Escape'){document.getElementById('sidebar')?.classList.remove('open');document.querySelector('[data-action=toggle-menu]')?.setAttribute('aria-expanded','false')}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal()}});
dialog.addEventListener('close',()=>{if(!dialog.open){state.modal=null;if(lastFocus?.isConnected)lastFocus.focus()}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);if(query().get('focus')==='attention')document.getElementById('attention')?.scrollIntoView({block:'center'});if(query().get('tab')==='locations'&&route().startsWith('certificates/')){for(const p of document.querySelectorAll('.panel'))if(['Locations','Konumlar'].includes(p.querySelector('h2')?.textContent))p.scrollIntoView({block:'start'})}if(query().get('section')==='components'){const panels=document.querySelectorAll('.panel');for(const p of panels)if(p.querySelector('h2')?.textContent.startsWith('05'))p.scrollIntoView({block:'start'})}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')render()});
render();
